package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarPathMutaGate1Test {

  @TempDir
  Path tempDir;

  private static void put(byte[] buf, int offset, String value) {
    byte[] b = value.getBytes(StandardCharsets.US_ASCII);
    System.arraycopy(b, 0, buf, offset, b.length);
  }

  private static byte[] minimalTar() {
    byte[] tar = new byte[512 + 1024];
    put(tar, 0, "hello.txt");
    put(tar, 100, "0000644");
    put(tar, 108, "0000000");
    put(tar, 116, "0000000");
    put(tar, 124, "00000000000");
    put(tar, 136, "00000000000");
    for (int i = 148; i < 156; i++) {
      tar[i] = ' ';
    }
    tar[156] = '0';
    put(tar, 257, "ustar");
    put(tar, 263, "00");
    int sum = 0;
    for (int i = 0; i < 512; i++) {
      sum += tar[i] & 0xff;
    }
    String chk = String.format("%06o", sum);
    put(tar, 148, chk);
    tar[154] = 0;
    tar[155] = ' ';
    return tar;
  }

  @Test
  void trailingSlashesAreStrippedFromEntryName() throws Exception {
    Path tar = tempDir.resolve("sample.tar");
    Files.write(tar, minimalTar());

    TarFileSystemProvider provider = new TarFileSystemProvider();
    try (TarFileSystem fs = (TarFileSystem) provider.newFileSystem(tar, Map.of())) {
      TarPath single = new TarPath(fs, false, "a/b/");
      assertEquals("a/b", single.entryName());
      assertEquals(2, single.getNameCount());

      TarPath multiple = new TarPath(fs, true, "a/b///");
      assertEquals("a/b", multiple.entryName());
      assertEquals("/a/b", multiple.toString());

      TarPath onlySlashes = new TarPath(fs, true, "////");
      assertEquals("", onlySlashes.entryName());
      assertEquals(0, onlySlashes.getNameCount());
      assertEquals("/", onlySlashes.toString());

      TarPath backslashes = new TarPath(fs, false, "x\\y\\");
      assertEquals("x/y", backslashes.entryName());

      TarPath empty = new TarPath(fs, false, "");
      assertEquals("", empty.entryName());
      assertTrue(empty.toString().isEmpty());

      assertEquals(new TarPath(fs, false, "a/b"), single);
    }
  }
}

