package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import org.junit.jupiter.api.Test;

class TarPathMutaGate3Test {

  private static void put(byte[] block, int offset, String value) {
    byte[] b = value.getBytes(StandardCharsets.US_ASCII);
    System.arraycopy(b, 0, block, offset, b.length);
  }

  private static byte[] minimalTar() {
    byte[] header = new byte[512];
    put(header, 0, "hello.txt");
    put(header, 100, "0000644\0");
    put(header, 108, "0000000\0");
    put(header, 116, "0000000\0");
    put(header, 124, "00000000000\0");
    put(header, 136, "00000000000\0");
    header[156] = '0';
    put(header, 257, "ustar\0");
    put(header, 263, "00");
    for (int i = 148; i < 156; i++) {
      header[i] = ' ';
    }
    int sum = 0;
    for (byte b : header) {
      sum += b & 0xff;
    }
    String chk = String.format("%06o", sum);
    put(header, 148, chk);
    header[154] = 0;
    header[155] = ' ';

    byte[] tar = new byte[512 + 1024];
    System.arraycopy(header, 0, tar, 0, 512);
    return tar;
  }

  @Test
  void trailingSlashesAreStrippedAndPlainNamesAreKept() throws Exception {
    Path tar = Files.createTempFile("mutagate3", ".tar");
    try {
      Files.write(tar, minimalTar());
      TarFileSystemProvider provider = new TarFileSystemProvider();
      try (TarFileSystem fs = (TarFileSystem) provider.newFileSystem(tar, Map.of())) {
        TarPath plain = new TarPath(fs, false, "a/b");
        assertEquals("a/b", plain.entryName());
        assertEquals(2, plain.getNameCount());
        assertEquals("a/b", plain.toString());
        assertEquals("b", plain.getFileName().toString());

        TarPath trailing = new TarPath(fs, false, "a/b/");
        assertEquals("a/b", trailing.entryName());
        assertEquals(2, trailing.getNameCount());
        assertEquals("a/b", trailing.toString());

        TarPath abs = new TarPath(fs, true, "/a/b//");
        assertEquals("/a/b", abs.toString());
        assertEquals(plain, new TarPath(fs, false, "a/b/"));

        TarPath root = new TarPath(fs, true, "///");
        assertEquals(0, root.getNameCount());
        assertEquals("/", root.toString());
      }
    } finally {
      Files.deleteIfExists(tar);
    }
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;

class TarPathMutaGate4Test {

  @Test
  void compareToOrdersPathsByStringForm() throws Exception {
    Path tar = Files.createTempFile("tarpath-compare", ".tar");
    try {
      Files.write(tar, new byte[1024]);
      TarFileSystemProvider provider = new TarFileSystemProvider();
      URI uri = URI.create("tar:" + tar.toAbsolutePath().toUri().getPath() + "!");
      TarFileSystem fs = new TarFileSystem(provider, uri, tar);

      TarPath a = new TarPath(fs, false, "a");
      TarPath b = new TarPath(fs, false, "b");
      TarPath aCopy = new TarPath(fs, false, "a");

      assertTrue(a.compareTo(b) < 0);
      assertTrue(b.compareTo(a) > 0);
      assertEquals(0, a.compareTo(aCopy));
    } finally {
      Files.deleteIfExists(tar);
    }
  }
}

