class TarPathMutaGate18Test {

  @TempDir
  Path tempDir;

  @Test
  void endsWithReturnsFalseWhenTrailingSegmentsDiffer() throws Exception {
    Path tar = tempDir.resolve("empty.tar");
    Files.write(tar, new byte[10240]);

