    put(tar, 116, "0000000\0");
    put(tar, 124, "00000000000\0");
    put(tar, 136, "00000000000\0");
    Arrays.fill(tar, 148, 156, (byte) ' ');
    tar[156] = '0';
    put(tar, 257, "ustar\0");
    put(tar, 263, "00");
    int sum = 0;
    for (int i = 0; i < 512; i++) {
