      assertNotSame(relative, madeAbsolute);
      assertFalse(relative.isAbsolute());

      TarPath absolute = new TarPath(tfs, true, "a/b");
      Path again = absolute.toAbsolutePath();
      assertSame(absolute, again);
      assertTrue(again.isAbsolute());
